// Line breaking for titles and captions. Pure Dart. The preview and the
// export both call [layoutTitleBlock] so that size, line breaks and position
// match.
//
// Widths are ESTIMATED from the advance widths of the bundled export fonts
// (assets/fonts/DejaVuSans.ttf and DejaVuSans-Bold.ttf, measured with
// fontTools from the hmtx table, in 1/1000 em; the other title fonts -
// Rubik, Bona Nova, Amatic SC - in title_font_metrics.dart, generated by
// docs/tools/title_font_metrics.py):
//
//   * Basic Latin, Latin-1, Cyrillic (U+0400..045F) and Hebrew letters use
//     the exact advance of each character (tables at the end of the file).
//   * Everything else uses an average-advance factor, see
//     [kFallbackAdvanceRegular] / [kFallbackAdvanceBold].
//
// For reference, the average advance per character (spaces included) of
// ordinary sentences, as a fraction of the font size, is:
//
//                regular   bold
//   English       0.52     0.58
//   Russian       0.58     0.64
//   Hebrew        0.49     0.53
//
// No kerning or shaping is applied. FFmpeg 6.1 and later shape text with
// HarfBuzz (kerning), so a line can come out a few pixels narrower than
// estimated; lines are centred (or aligned) on drawtext's own measure.

import 'dart:math' as math;

import 'project.dart';

part 'title_font_metrics.dart';

/// The font file of [font] (bold cut when [bold]) in assets/fonts, the same
/// file for the preview and for ffmpeg's drawtext.
String titleFontFileName(TitleFont font, bool bold) => switch (font) {
      TitleFont.classic => bold ? 'DejaVuSans-Bold.ttf' : 'DejaVuSans.ttf',
      TitleFont.modern => bold ? 'Rubik-Bold.ttf' : 'Rubik-Regular.ttf',
      TitleFont.elegant =>
        bold ? 'BonaNova-Bold.ttf' : 'BonaNova-Regular.ttf',
      TitleFont.handwritten =>
        bold ? 'AmaticSC-Bold.ttf' : 'AmaticSC-Regular.ttf',
    };

/// Every bundled title font file, regular and bold.
List<String> get allTitleFontFiles => [
      for (final f in TitleFont.values) ...[
        titleFontFileName(f, false),
        titleFontFileName(f, true),
      ],
    ];

/// The name of [font] in the app ("Classic", "Modern", ...).
String titleFontLabel(TitleFont font) => switch (font) {
      TitleFont.classic => 'Classic',
      TitleFont.modern => 'Modern',
      TitleFont.elegant => 'Elegant',
      TitleFont.handwritten => 'Handwritten',
    };

/// "Fade", "Slide up", "Pop", "None".
String titleAnimationLabel(TitleAnimation a) => switch (a) {
      TitleAnimation.none => 'None',
      TitleAnimation.fade => 'Fade',
      TitleAnimation.slideUp => 'Slide up',
      TitleAnimation.pop => 'Pop',
    };

/// Thickness of a title's outline, as a share of the font size (at least 1
/// pixel).
const double kTitleOutlineFraction = 0.06;

/// Outline width in pixels for a font size of [fontPx] pixels.
int titleOutlinePx(double fontPx) => math.max(1, (fontPx * kTitleOutlineFraction).round());

/// Longest time an entry or exit animation takes.
const int kTitleAnimationMs = 400;

/// How far a "slide up" moves, as a share of the canvas height.
const double kTitleSlideFraction = 0.06;

/// Smallest size of a "pop", as a share of the full size.
const double kTitlePopFrom = 0.6;

/// Overshoot of a "pop" on the way in.
const double kTitlePopOvershoot = 0.12;

/// Lengths of the entry and exit animation of [t] in ms: at most
/// [kTitleAnimationMs], at most half the title each; 0 when there is none.
({int inMs, int outMs}) titleAnimationLengths(TitleOverlay t) {
  final half = math.max(0, (t.endMs - t.startMs) ~/ 2);
  int len(TitleAnimation a) =>
      a == TitleAnimation.none ? 0 : math.min(kTitleAnimationMs, half);
  return (inMs: len(t.animIn), outMs: len(t.animOut));
}

/// Where an animated title is at [timeMs] (timeline): its opacity (0..1),
/// how far it is moved down (as a share of the canvas height; negative =
/// up) and its size (1 = as laid out). The export builds the same curves as
/// ffmpeg expressions (lib/media/ffmpeg_command.dart, titleAnimationExpr);
/// a background box takes the opacity and the move but keeps its size.
///
///  * fade: opacity 0 -> 1 (in) / 1 -> 0 (out), linear;
///  * slide up: fades too, and rises [kTitleSlideFraction] of the canvas,
///    slowing down (in: from below; out: on upwards);
///  * pop: grows from [kTitlePopFrom] with a small overshoot (in), shrinks
///    back (out), and is fully visible after the first third.
({double alpha, double dy, double scale}) titleAnimationAt(
    TitleOverlay t, int timeMs) {
  final lens = titleAnimationLengths(t);
  var alpha = 1.0, dy = 0.0, scale = 1.0;
  double unit(double v) => v < 0 ? 0 : (v > 1 ? 1 : v);
  if (lens.inMs > 0) {
    final p = unit((timeMs - t.startMs) / lens.inMs);
    switch (t.animIn) {
      case TitleAnimation.none:
        break;
      case TitleAnimation.fade:
        alpha *= p;
      case TitleAnimation.slideUp:
        alpha *= p;
        dy += kTitleSlideFraction * (1 - p) * (1 - p);
      case TitleAnimation.pop:
        alpha *= math.min(1, 3 * p);
        scale *= kTitlePopFrom +
            (1 - kTitlePopFrom) * (1 - math.pow(1 - p, 3)) +
            kTitlePopOvershoot * math.sin(math.pi * p);
    }
  }
  if (lens.outMs > 0) {
    final q = unit((t.endMs - timeMs) / lens.outMs);
    switch (t.animOut) {
      case TitleAnimation.none:
        break;
      case TitleAnimation.fade:
        alpha *= q;
      case TitleAnimation.slideUp:
        alpha *= q;
        dy -= kTitleSlideFraction * (1 - q) * (1 - q);
      case TitleAnimation.pop:
        alpha *= math.min(1, 3 * q);
        scale *= kTitlePopFrom +
            (1 - kTitlePopFrom) * (1 - math.pow(1 - q, 3));
    }
  }
  return (alpha: unit(alpha), dy: dy, scale: scale);
}

/// A ready-made title look ("Style"): what a tap on it sets. Text, times,
