/// Where a title goes when a position button is used: top, middle, lower
/// third or bottom (the layout keeps it inside the picture).
enum TitlePosition { top, middle, lowerThird, bottom }

/// The `y` of [p] (centre of the text, share of the canvas height).
double titlePositionY(TitlePosition p) => switch (p) {
      TitlePosition.top => 0.1,
      TitlePosition.middle => 0.5,
      TitlePosition.lowerThird => 0.75,
      TitlePosition.bottom => 0.9,
    };

String titlePositionLabel(TitlePosition p) => switch (p) {
      TitlePosition.top => 'Top',
      TitlePosition.middle => 'Middle',
      TitlePosition.lowerThird => 'Lower third',
      TitlePosition.bottom => 'Bottom',
    };

/// The `x` that goes with [a]: left- and right-aligned text sits against
/// that side (the layout keeps the margin), centred text in the middle.
double titleAlignX(TitleAlign a) => switch (a) {
      TitleAlign.center => 0.5,
      TitleAlign.left => 0.0,
      TitleAlign.right => 1.0,
    };

/// Share of the canvas width a line of text may take.
const double kTitleMaxWidthFraction = 0.9;

/// Average advance (fraction of the font size) used for characters that
/// have no measured value: the mean over the other letters of DejaVu Sans
/// (Greek, extended Latin and Cyrillic, Arabic, ...).
const double kFallbackAdvanceRegular = 0.67;
const double kFallbackAdvanceBold = 0.75;

/// Advance used for wide East Asian characters and emoji (one full em).
const double kWideAdvance = 1.0;

/// Look of a caption (subtitle): bottom centre, white bold text in a box.
abstract final class CaptionDefaults {
  static const TitleKind kind = TitleKind.caption;
  static const double x = 0.5;
  static const double y = 0.86;
  static const double fontSize = 0.045;
  static const int colorArgb = 0xFFFFFFFF;
  static const bool bold = true;
  static const bool background = true;
}

/// [t] with the caption look ([CaptionDefaults]); id, text and times are
/// kept.
TitleOverlay captionStyle(TitleOverlay t) => t.copyWith(
      kind: CaptionDefaults.kind,
      x: CaptionDefaults.x,
      y: CaptionDefaults.y,
      fontSize: CaptionDefaults.fontSize,
      colorArgb: CaptionDefaults.colorArgb,
      bold: CaptionDefaults.bold,
      background: CaptionDefaults.background,
    );

/// Margin kept between a title block and the canvas edge, as a fraction of
/// the canvas width (left / right) and height (top / bottom).
const double kTitleMarginFraction = 0.02;

/// Line height as a multiple of the font size.
const double kTitleLineHeight = 1.2;

/// Padding of the background box as a multiple of the font size.
const double kTitleBoxPad = 0.3;

/// Font size in pixels of [t] (rounded the same way for preview and export,
/// at least 1).
///
/// The size is [TitleOverlay.fontSize] times the SHORT side of the canvas,
/// so that text does not balloon on portrait canvases. Pass [canvasWidth]
/// to get that; without it [canvasHeight] alone is used, which is the same
/// thing for landscape and square canvases.
int titleFontPx(TitleOverlay t, int canvasHeight, [int? canvasWidth]) {
  final basis = canvasWidth != null && canvasWidth > 0 && canvasWidth < canvasHeight
      ? canvasWidth
      : canvasHeight;
  final px = t.fontSize * basis;
  if (px.isNaN || px < 1) return 1;
  return px.isInfinite ? (basis < 1 ? 1 : basis) : px.round();
}

/// Widest a line of [t] may be, in pixels: [kTitleMaxWidthFraction] of the
/// canvas, less when the background box would otherwise not fit inside the
/// margins.
double _maxLineWidth(TitleOverlay t, int canvasWidth, int fontPx) {
  final byFraction = canvasWidth * kTitleMaxWidthFraction;
  if (!t.background) return byFraction;
  final byBox =
      canvasWidth * (1 - 2 * kTitleMarginFraction) - 2 * kTitleBoxPad * fontPx;
  return byBox < byFraction ? byBox : byFraction;
}

/// A title laid out on a canvas: its lines and where they go, in canvas
/// pixels. The preview and the export both draw from this, so that they
/// agree on size, line breaks and position.
class TitleBlock {
  const TitleBlock({
    required this.lines,
    required this.fontPx,
    required this.lineHeightPx,
    required this.boxPadPx,
    required this.centerX,
    required this.centerY,
    required this.width,
    required this.height,
  });

  /// The lines of text, top to bottom (see [layoutTitleLines]). Unmodifiable.
  final List<String> lines;
  final double fontPx;

  /// Distance between the tops of two lines: 1.2 x [fontPx].
  final double lineHeightPx;

  /// Space between the text and the edge of the background box on every
  /// side: 0.3 x [fontPx], or 0 when the title has no background.
  final double boxPadPx;

  /// Centre of the block. Starts from the title's x / y and is moved as far
  /// as needed to keep the whole block (text plus [boxPadPx]) inside the
  /// canvas with a 2% margin. A block that is too large to fit is centred.
  final double centerX;
  final double centerY;

  /// Size of the TEXT (without [boxPadPx]): the estimated width of the
  /// widest line, and `lines.length * lineHeightPx`.
  final double width;
  final double height;

  /// Edges of the text.
  double get left => centerX - width / 2;
  double get top => centerY - height / 2;

  /// Edges of the block including the box padding.
  double get boxLeft => left - boxPadPx;
  double get boxTop => top - boxPadPx;
  double get boxWidth => width + 2 * boxPadPx;
  double get boxHeight => height + 2 * boxPadPx;
}

/// Lays [t] out on a canvas of the given size; see [TitleBlock].
TitleBlock layoutTitleBlock(
  TitleOverlay t, {
  required int canvasWidth,
  required int canvasHeight,
}) {
  final lines = List<String>.unmodifiable(layoutTitleLines(t,
      canvasWidth: canvasWidth, canvasHeight: canvasHeight));
  final fontPx = titleFontPx(t, canvasHeight, canvasWidth).toDouble();
  final lineHeight = kTitleLineHeight * fontPx;
  final pad = t.background ? kTitleBoxPad * fontPx : 0.0;
  var width = 0.0;
  for (final line in lines) {
    final w =
        estimateTextWidth(line, fontPx: fontPx, bold: t.bold, font: t.font);
    if (w > width) width = w;
  }
  final height = lines.length * lineHeight;

  double place(double fraction, int canvas, double size) {
    final c = canvas.toDouble();
    final wanted = (fraction.isNaN ? 0.5 : fraction) * c;
    final half = size / 2 + pad;
    final lo = c * kTitleMarginFraction + half;
    final hi = c * (1 - kTitleMarginFraction) - half;
    if (hi < lo) return c / 2;
    return wanted < lo ? lo : (wanted > hi ? hi : wanted);
  }

  return TitleBlock(
    lines: lines,
    fontPx: fontPx,
    lineHeightPx: lineHeight,
    boxPadPx: pad,
    centerX: place(t.x, canvasWidth, width),
    centerY: place(t.y, canvasHeight, height),
    width: width,
    height: height,
  );
}

/// Estimated width in pixels of [text] (one line) drawn at [fontPx] pixels
/// in [font] (DejaVu Sans by default; its bold cut when [bold]).
double estimateTextWidth(String text,
    {required num fontPx,
    required bool bold,
    TitleFont font = TitleFont.classic}) {
  var em = 0;
  for (final r in text.runes) {
    em += _advance(r, bold, font);
  }
  return em * fontPx / 1000;
}

/// The lines [t] is drawn as on a canvas of the given size.
///
/// The text is split at explicit newlines; each of those lines is then
/// word-wrapped so that its estimated width is at most
/// [kTitleMaxWidthFraction] of [canvasWidth] (less for a boxed title whose
/// box would otherwise cross the 2% margin). The font size comes from the
/// canvas SHORT side, see [titleFontPx]. Runs of spaces collapse to
/// one space and lines are trimmed. A single word that is too wide is
/// broken between characters. Empty lines are kept (as ''), and the result
/// always has at least one line.
List<String> layoutTitleLines(
  TitleOverlay t, {
  required int canvasWidth,
  required int canvasHeight,
}) {
  final fontPx = titleFontPx(t, canvasHeight, canvasWidth);
  final maxEm = canvasWidth <= 0
      ? double.infinity
      // Width limit in 1/1000 em, with a hair of slack for rounding.
      : _maxLineWidth(t, canvasWidth, fontPx) * 1000 / fontPx + 1e-6;
  final spaceEm = _advance(0x20, t.bold, t.font);
  final lines = <String>[];
  final paragraphs =
      t.text.replaceAll('\r\n', '\n').replaceAll('\r', '\n').split('\n');
  for (final paragraph in paragraphs) {
    final words = [
      for (final w in paragraph.split(_spaces))
        if (w.isNotEmpty) w,
    ];
    if (words.isEmpty) {
      lines.add('');
      continue;
    }
    var line = StringBuffer();
    var lineEm = 0;
    for (final word in words) {
      final wordEm = _widthEm(word, t.bold, t.font);
      if (lineEm > 0 && lineEm + spaceEm + wordEm <= maxEm) {
        line
          ..write(' ')
          ..write(word);
        lineEm += spaceEm + wordEm;
        continue;
      }
      if (lineEm > 0) {
        lines.add(line.toString());
        line = StringBuffer();
        lineEm = 0;
      }
      if (wordEm <= maxEm) {
        line.write(word);
        lineEm = wordEm;
        continue;
      }
      // Too wide even alone: break between characters. The last piece
      // stays open so that following words can join it.
      for (final cluster in _clusters(word)) {
        final clusterEm = _widthEm(cluster, t.bold, t.font);
        if (lineEm > 0 && lineEm + clusterEm > maxEm) {
          lines.add(line.toString());
          line = StringBuffer();
          lineEm = 0;
        }
        line.write(cluster);
        lineEm += clusterEm;
      }
    }
    lines.add(line.toString());
  }
  return lines;
}

final RegExp _spaces = RegExp(r'[ \t 　]+');

int _widthEm(String s, bool bold, TitleFont font) {
  var em = 0;
  for (final r in s.runes) {
    em += _advance(r, bold, font);
  }
  return em;
}

/// Splits [word] into pieces that may be separated by a line break: one
/// character each, with combining marks, variation selectors and joined
/// emoji kept together with the character before them.
List<String> _clusters(String word) {
  final out = <String>[];
  var current = StringBuffer();
  var joinNext = false;
  for (final r in word.runes) {
    final attach = _isZeroWidth(r) || joinNext;
    if (!attach && current.isNotEmpty) {
      out.add(current.toString());
      current = StringBuffer();
    }
    current.writeCharCode(r);
    joinNext = r == 0x200D; // zero width joiner
  }
  if (current.isNotEmpty) out.add(current.toString());
  return out;
}

bool _isZeroWidth(int r) =>
    (r >= 0x0300 && r <= 0x036F) || // combining diacritics
    (r >= 0x0483 && r <= 0x0489) || // Cyrillic combining
    (r >= 0x0591 && r <= 0x05BD) || // Hebrew accents and points
    r == 0x05BF ||
    r == 0x05C1 ||
    r == 0x05C2 ||
    r == 0x05C4 ||
    r == 0x05C5 ||
    r == 0x05C7 ||
    (r >= 0x0610 && r <= 0x061A) || // Arabic marks
    (r >= 0x064B && r <= 0x065F) ||
    (r >= 0x200B && r <= 0x200F) || // zero width space, joiners, marks
    (r >= 0x202A && r <= 0x202E) || // bidi controls
    (r >= 0x2060 && r <= 0x2064) ||
    (r >= 0x20D0 && r <= 0x20FF) || // combining marks for symbols
    (r >= 0xFE00 && r <= 0xFE0F) || // variation selectors
    (r >= 0xFE20 && r <= 0xFE2F) ||
    r == 0xFEFF ||
    (r >= 0x1F3FB && r <= 0x1F3FF); // emoji skin tones

bool _isWide(int r) =>
    (r >= 0x1100 && r <= 0x115F) || // Hangul Jamo
    (r >= 0x2E80 && r <= 0xA4CF) || // CJK, kana, ...
    (r >= 0xAC00 && r <= 0xD7A3) || // Hangul syllables
    (r >= 0xF900 && r <= 0xFAFF) ||
    (r >= 0xFE30 && r <= 0xFE4F) ||
    (r >= 0xFF00 && r <= 0xFF60) || // fullwidth forms
    (r >= 0xFFE0 && r <= 0xFFE6) ||
    (r >= 0x1F000 && r <= 0x1FAFF) || // emoji
    (r >= 0x20000 && r <= 0x3FFFD);

/// Advance of one character in 1/1000 em, in [font].
int _advance(int r, bool bold, [TitleFont font = TitleFont.classic]) {
  if (font != TitleFont.classic) return _otherAdvance(r, bold, font);
  if (r < 0x20) return r == 0x09 ? _advance(0x20, bold) : 0;
  if (r <= 0x7E) return (bold ? _asciiBold : _asciiRegular)[r - 0x20];
  if (r < 0xA0) return 0;
  if (r <= 0xFF) return (bold ? _latin1Bold : _latin1Regular)[r - 0xA0];
  if (r >= 0x400 && r <= 0x45F) {
    return (bold ? _cyrillicBold : _cyrillicRegular)[r - 0x400];
  }
  if (r >= 0x5D0 && r <= 0x5EA) {
    return (bold ? _hebrewBold : _hebrewRegular)[r - 0x5D0];
  }
  if (_isZeroWidth(r)) return 0;
  if (_isWide(r)) return (kWideAdvance * 1000).round();
  return ((bold ? kFallbackAdvanceBold : kFallbackAdvanceRegular) * 1000)
      .round();
}

