/// [_advance] for the fonts of title_font_metrics.dart.
int _otherAdvance(int r, bool bold, TitleFont font) {
  final t = switch (font) {
    TitleFont.modern => bold
        ? (_rubikBoldAscii, _rubikBoldLatin1, _rubikBoldCyrillic,
            _rubikBoldHebrew, _rubikBoldFallback)
        : (_rubikRegularAscii, _rubikRegularLatin1, _rubikRegularCyrillic,
            _rubikRegularHebrew, _rubikRegularFallback),
    TitleFont.elegant => bold
        ? (_bonaNovaBoldAscii, _bonaNovaBoldLatin1, _bonaNovaBoldCyrillic,
            _bonaNovaBoldHebrew, _bonaNovaBoldFallback)
        : (_bonaNovaRegularAscii, _bonaNovaRegularLatin1,
            _bonaNovaRegularCyrillic, _bonaNovaRegularHebrew,
            _bonaNovaRegularFallback),
    _ => bold
        ? (_amaticScBoldAscii, _amaticScBoldLatin1, _amaticScBoldCyrillic,
            _amaticScBoldHebrew, _amaticScBoldFallback)
        : (_amaticScRegularAscii, _amaticScRegularLatin1,
            _amaticScRegularCyrillic, _amaticScRegularHebrew,
            _amaticScRegularFallback),
  };
  int pick(List<int> table, int i) {
    final v = table[i];
    return v < 0 ? t.$5 : v;
  }

  if (r < 0x20) return r == 0x09 ? pick(t.$1, 0) : 0;
  if (r <= 0x7E) return pick(t.$1, r - 0x20);
  if (r < 0xA0) return 0;
  if (r <= 0xFF) return pick(t.$2, r - 0xA0);
  if (r >= 0x400 && r <= 0x45F) return pick(t.$3, r - 0x400);
  if (r >= 0x5D0 && r <= 0x5EA) return pick(t.$4, r - 0x5D0);
  if (_isZeroWidth(r)) return 0;
  if (_isWide(r)) return (kWideAdvance * 1000).round();
  return t.$5;
}
